    'emp.help_center.guide.request_leave_opt_multi_day_label'  => ['en' => 'Multi-day mode', 'th' => 'รูปแบบหลายวัน'],
    'emp.help_center.guide.request_leave_opt_multi_day_desc'   => ['en' => 'Pick a start and end date (inclusive). Non-working days are excluded from the charge.', 'th' => 'เลือกวันที่เริ่มต้นและสิ้นสุด (รวม) วันไม่ทำการจะถูกยกเว้นจากการนับ'],
    'emp.help_center.guide.request_leave_opt_reason_label'     => ['en' => 'Reason (optional)', 'th' => 'เหตุผล (ไม่บังคับ)'],
    'emp.help_center.guide.request_leave_opt_reason_desc'      => ['en' => 'Add a note explaining your leave request.', 'th' => 'เพิ่มหมายเหตุอธิบายคำขอลาของคุณ'],
    'emp.help_center.guide.request_leave_opt_attachment_label' => ['en' => 'Attachment link (optional)', 'th' => 'ลิงก์เอกสารแนบ (ไม่บังคับ)'],
    'emp.help_center.guide.request_leave_opt_attachment_desc'  => ['en' => 'Paste a link to a supporting document such as a medical certificate.', 'th' => 'วางลิงก์เอกสารประกอบ เช่น ใบรับรองแพทย์'],
