    'emp.help_center.guide.request_leave_warning' => ['en' => 'Important: Your request is blocked if the calculated leave exceeds your remaining balance for that leave type and year. Contact HR if you need leave beyond your quota.', 'th' => 'สำคัญ: คำขอของคุณจะถูกบล็อกหากการลาที่คำนวณได้เกินยอดคงเหลือสำหรับประเภทและปีนั้น ติดต่อฝ่ายบุคคลหากคุณต้องการลาเกินโควต้า'],
    'emp.help_center.guide.request_leave_step1' => ['en' => 'Click "Request Leave" in the sidebar to open the form.', 'th' => 'คลิก "ขอลา" ในแถบด้านข้างเพื่อเปิดแบบฟอร์ม'],
    'emp.help_center.guide.request_leave_step2' => ['en' => 'Select a leave type — the allowed modes update automatically.', 'th' => 'เลือกประเภทการลา — รูปแบบที่อนุญาตจะอัปเดตอัตโนมัติ'],
    'emp.help_center.guide.request_leave_step3' => ['en' => 'Pick the dates/hours and optionally add a reason or attachment link.', 'th' => 'เลือกวันที่/ชั่วโมงและเพิ่มเหตุผลหรือลิงก์เอกสารแนบ (ไม่บังคับ)'],
    'emp.help_center.guide.request_leave_step4' => ['en' => 'Submit the form. If within quota, your request appears as "pending" on the Leave Requests page.', 'th' => 'ส่งแบบฟอร์ม หากอยู่ในโควต้า คำขอของคุณจะปรากฏเป็น "รออนุมัติ" บนหน้าคำขอลา'],

    // ---- help center: change password guide ----
    'emp.help_center.guide.change_password_title' => ['en' => 'Change Password', 'th' => 'เปลี่ยนรหัสผ่าน'],
    'emp.help_center.guide.change_password_desc'  => ['en' => 'Change your password voluntarily, or when forced by HR on first login.', 'th' => 'เปลี่ยนรหัสผ่านด้วยตัวเอง หรือเมื่อฝ่ายบุคคลบังคับในการเข้าสู่ระบบครั้งแรก'],
