    'emp.help_center.guide.change_password_warning' => ['en' => 'Best practice: Choose a unique password you do not reuse on other sites. Change it immediately if you suspect unauthorized access.', 'th' => 'แนวปฏิบัติที่ดี: เลือกรหัสผ่านที่ไม่ซ้ำกับเว็บไซต์อื่น เปลี่ยนทันทีหากคุณสงสัยว่ามีการเข้าถึงโดยไม่ได้รับอนุญาต'],
    'emp.help_center.guide.change_password_step1' => ['en' => 'Click "Change Password" in the sidebar (or follow the forced-change prompt).', 'th' => 'คลิก "เปลี่ยนรหัสผ่าน" ในแถบด้านข้าง (หรือทำตามพร้อมท์การเปลี่ยนที่บังคับ)'],
    'emp.help_center.guide.change_password_step2' => ['en' => 'Enter and confirm your new password — the strength meter and checklist guide you.', 'th' => 'กรอกและยืนยันรหัสผ่านใหม่ — มิเตอร์และรายการเกณฑ์จะช่วยแนะนำคุณ'],
    'emp.help_center.guide.change_password_step3' => ['en' => 'Submit. You are redirected to the dashboard once the password is updated.', 'th' => 'ส่ง คุณจะถูกนำไปยังแดชบอร์ดเมื่อรหัสผ่านอัปเดตแล้ว'],

    // ---- help center: language guide ----
